								return;
							}

							sourceCapsule.CopyTo(destCapsule);
							msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Seal, ResultCopySealMessageLabel, true, false, null, onEnd);
						}, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
					}, null);
				});
			}
			else
			{
				msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Seal, DontCopyNotEnoughSealMessageLabel, true, false, null, onCancel);
			}
		}
		private void OpenCapsuleContextMenu(global::Dpr.UI.CapsuleItemButton capsuleItemButton) {
			CapsuleInfo capsuleInfo = capsuleItemButton.GetInfo();
            void OnSelected(ContextMenuID menuID)
			{
				msgWindowController.CloseMsgWindow();
				Audio.AudioManager.Instance.PlaySe(menuID == ContextMenuID.SEAL_CAPSULE_SWAP ? AK.EVENTS.UI_COMMON_DONE : AK.EVENTS.UI_COMMON_DECIDE, null);
				switch (menuID)
				{
					case ContextMenuID.SEAL_CAPSULE_ATTACH_POKEMON:
						BoxWindow box = UIManager.Instance.CreateUIWindow<BoxWindow>(UIWindowID.BOX);
						box.onClosed += _ =>
						{
							UIManager.Instance.SetTransitionWindowIds(box.instance.windowId, instance.windowId, true);
							Audio.AudioManager.Instance.SetBgmEvent(AK.EVENTS.DUCKON_BGM, false);
							capsuleViewController.View3DController.SetEnviromentControllerActive(true);
							capsuleViewController.Set3DCapsuleActive(true);
							keyguide = null;
							UpdateKeyGuide();
						};
						BoxWindow.OpenParam openParam = new BoxWindow.OpenParam()
						{
							openType = BoxWindow.OpenType.External,
							selectCount = 1,
							isEnableDying = true,
							isEnableEgg = false,
							isEnableTeam = true,
							isEnableParty = true,
						};
						UIManager.Instance.SetTransitionWindowIds(instance.windowId, box.instance.windowId, false);
						box.Open(openParam, (window, selected) =>
						{
							BoxWindow.SelectedPokemon selectedPokemon = selected[0];
							if (selectedPokemon.Param == null)
								return;

							capsuleInfo.AttachPokemon(selectedPokemon.Param, selectedPokemon.TrayIndex, selectedPokemon.IndexInTray);
							TvWork.CustumBallSakusei(capsuleInfo.Data.AffixSealDatas[0].SealId, capsuleInfo.AttachPokemonParam.GetMonsNo());
							ReloadScrollView();
						}, instance.windowId);
						capsuleViewController.Set3DCapsuleActive(false);
						capsuleViewController.View3DController.SetEnviromentControllerActive(false);
						break;
					case ContextMenuID.SEAL_CAPSULE_DETACH_POKEMON:
						capsuleInfo.DetachPokemon();
						ReloadScrollView();
						break;
					case ContextMenuID.SEAL_CAPSULE_AFFIX_SEAL:
						if (capsuleInfo.IsAppliedTemplate)
						{
							msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Seal, CantAffixSealMessageLabel, true, false, null, capsuleItemButton.OnContextMenuClose);
							return;
						}
						ShowEditMode(capsuleInfo);
						break;
					case ContextMenuID.SEAL_CAPSULE_REMOVE_ALL_SEAL:
						StartRemoveAllAffixSeals(capsuleItemButton);
						return;
					case ContextMenuID.SEAL_CAPSULE_SWAP:
						capsuleItemButton.OnContextMenuClose();
						StartCapsuleAction(ActionType.Swap, capsuleItemButton);
						return;
					case ContextMenuID.SEAL_CAPSULE_COPY:
						capsuleItemButton.OnContextMenuClose();
						StartCapsuleAction(ActionType.Copy, capsuleItemButton);
						return;
				}
				capsuleItemButton.OnContextMenuClose();
			}

			if (capsuleInfo == null)
				return;

			List<ContextMenuID> contextMenuIdList = new List<ContextMenuID>();
			contextMenuIdList.Add(ContextMenuID.SEAL_CAPSULE_AFFIX_SEAL);
			contextMenuIdList.Add(capsuleInfo.AttachPokemonParam != null ? ContextMenuID.SEAL_CAPSULE_DETACH_POKEMON : ContextMenuID.SEAL_CAPSULE_ATTACH_POKEMON);
			if (capsuleInfo.IsAffixedSeal)
				contextMenuIdList.Add(ContextMenuID.SEAL_CAPSULE_REMOVE_ALL_SEAL);
			if (capsuleInfo.IsAffixedSeal)
				contextMenuIdList.Add(ContextMenuID.SEAL_CAPSULE_COPY);
			contextMenuIdList.Add(ContextMenuID.SEAL_CAPSULE_SWAP);
			contextMenuIdList.Add(ContextMenuID.SEAL_CAPSULE_CANCEL);
			capsuleItemButton.OnContextMenuOpen();
			msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Seal, QuestionCapsuleActionMessageLabel, true, false, () =>
			{
				msgWindowController.HideKeywaitIcon();
				OpenContextMenu(contextMenuIdList.ToArray(), OnSelected, contextMenuPosition.pivot, contextMenuPosition.position, null);
			}, null);
        }
		private void OpenContextMenu(global::ContextMenuID[] contextMenuIDs, global::System.Action<global::ContextMenuID> onSelected, global::UnityEngine.Vector2 pivot, global::UnityEngine.Vector3 pos, global::System.Action onClosed = null) {
			ContextMenuWindow.Param param = new ContextMenuWindow.Param();
			param.itemParams = new ContextMenuItem.Param[contextMenuIDs.Length];
			for (int i = 0; i < contextMenuIDs.Length; i++)
				param.itemParams[i] = new ContextMenuItem.Param() { menuId = contextMenuIDs[i] };
			param.pivot = pivot;
			param.position = pos;
			param.minItemWidth = 122f;
			param.useLoopAndRepeat = false;
			param.seDecide = 0;
			param.seCancel = 0;

			ContextMenuWindow contextMenu = UIManager.Instance.CreateUIWindow<ContextMenuWindow>(UIWindowID.CONTEXTMENU);
			contextMenu.onClosed = _ => onClosed?.Invoke();
			contextMenu.onClicked = item =>
			{
				onSelected?.Invoke(item.param.menuId);
				return true;
			};
			contextMenu.Open(param);
		}
		public UISeal() { }
		static UISeal() { }
		private enum ActionType
		{
			None = 0,
			Copy = 1,
			Swap = 2,
			CopyOnly = 3,
		}
	}
}
